	val = readl(base + 0x0);

	if (copy_to_user(buf, &val, sizeof(val)))
		return -EFAULT;

	*off += 0x4;
	return sizeof(val);
}

static ssize_t edu_write(struct file *filp, const char __user *buf, size_t len, loff_t *off)
